import {makeEngine,canonical} from './engine.mjs';
import {prepareImport,MAX_IMPORT_BYTES} from './import-graph.mjs';
import {loadDictionaries} from './dictionary-loader.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const acronyms=new Set('ABIL ACWB AFNI AMT CAD CCA CPP CRA CWB EI FHSA GST HBP HST IRS ITA ITC JSON LLP LPP NS OAS PA PAR PRPP PSPA QPP RDSP RRSP SPP TFSA TOSI UCCB UUID XML'.split(' '));
const label=p=>p.split('/').at(-1).replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/([A-Z])([A-Z][a-z])/g,'$1 $2').replace(/\b[a-z]+\b/gi,word=>acronyms.has(word.toUpperCase())?word.toUpperCase():word).replace(/^./,c=>c.toUpperCase());
const groups=[
 ['Return & residence',['return','person','residence'],'Choose the taxation year and record the taxpayer’s circumstances. Nova Scotia selects an explicit 2025 or 2026 parameter pack; federal income remains a reviewed foundation.'],
 ['Family',['dependants'],'Add the people relevant to dependency and family-based provisions.'],
 ['Income sources',['employments','businesses','properties','otherIncome'],'Add each distinct source. Count each amount only once. If Schedule 7 is enabled, exclude its HBP/LLP repayment shortfalls from these generic records.'],
 ['Capital gains & losses',['capital'],'Enter taxable gains and allowable losses after the relevant legal adjustments.'],
 ['Deductions',['subdivisionEDeductions','divisionCDeductions','taxableIncome'],'Record permitted deductions after eligibility, limits, and ordering have been reviewed. If Schedule 7 is enabled, exclude its RRSP deduction from these generic records.'],
 ['Schedule options',['scheduleSetup'],'Enable Schedule 9 or Schedule 7 to link their results into the tax calculation. Older saved graphs retain manual handling until you enable a schedule. For Schedule 7, remove the same RRSP deduction and HBP/LLP shortfalls from generic records first.'],
 ['Donations & gifts',['donations'],'Schedule 9: record eligible gift pools by origin year and category, elect the amounts to claim, and review income limits and carryforwards. One claim feeds both federal and Nova Scotia tax.'],
 ['RRSP room · T4040',['rrspRoom'],'Calculate room for the selected return year from the PREVIOUS year’s earned income and deductions, plus pension adjustments. Compare the estimate with your latest CRA assessment. Deduction room and undeducted contributions are different amounts.'],
 ['RRSP · Schedule 7',['rrspSchedule'],'Choose the source of your deduction limit, enter contributions and HBP/LLP designations, then elect your deduction. Enabling the schedule automatically posts the reviewed deduction and shortfall income once.'],
 ['Plans & loss balances',['registeredPlans','lossBalances'],'Schedule 7 posts its linked RRSP deduction and HBP/LLP shortfalls automatically when enabled. Other registered-plan amounts still need the appropriate generic income/deduction entry once.'],
 ['Federal credits',['credits'],'Choose Credit input basis first. Claim amounts are multiplied by 14.5% in 2025 (14% in 2026). Donations, top-up, dividend, foreign and political fields always take final credit dollars. Leave Basic personal blank for automatic calculation. Use Credit dollars only for already-calculated reductions.'],
 ['Other tax & filing',['specialTaxes','payments','filing','benefits'],'Record special schedules and payments. Minimum tax means the final T691 line 41700 amount when that schedule is selected. Registered-plan taxes on separate returns and non-resident withholding are outside this ordinary return.'],
 ['Nova Scotia · scope',['nsSetup'],'This separate dictionary references your federal income and personal facts. Supported years: 2025 and 2026. Confirm the ordinary-return scope before using the provincial result.'],
 ['Nova Scotia · credits',['nsCredits'],'Provide reviewed provincial amounts. A base amount is the qualifying amount before the 8.79% credit rate. Enter zero explicitly when no amount applies.'],
 ['Nova Scotia · reduction',['nsReduction'],'If not claiming the low-income reduction, choose No; its family-income and dependant fields may then remain blank.'],
 ['Nova Scotia · tax',['nsAdjustments','nsTax','nsParameters'],'Review special adjustments and inspect provincial tax after credits. Federal tax, payments and refundable NS479 credits are outside this result. Annual parameters are available in the graph explorer.'],
 ['Federal tax',['federalAdjustments','federalCalculation','federalParameters'],'Follow tax on taxable income through nonrefundable credits, basic federal tax and net federal tax. Confirm special schedules and review before using the final result.'],
 ['Refundable credits',['refundableCredits'],'Enter reviewed refundable credits and overpayments, or confirmed zero. Tax withheld and instalments are entered under Other tax & filing. Do not include separately paid GST/HST or child benefits.'],
 ['Balance owing / refund',['settlement'],'Combine net federal tax with Nova Scotia tax, CPP/EI payable and social benefits repayment, then subtract payments and refundable credits. This is a calculated return balance, not a CRA account balance.'],
 ['Review & calculations',['review','income','nextYearRrsp'],'Review the income calculation and estimate next year’s RRSP deduction limit using T4040 Chart 3. Enter the selected return year’s earned-income components here; investment income is not automatically earned income. Enter expected next-year adjustments explicitly, including zero when none apply. The result is an estimate to compare with CRA’s assessment.']
];
let engine,catalogue,graph,inputs={},drafts={},errors={},step=0,selected='/taxableIncome/amount',view='interview';
const fieldId=p=>'f-'+p.replace(/[^a-zA-Z0-9]/g,'-');
function concrete(f){if(!f.path.includes('/*/'))return[f.path];const [root,suffix]=f.path.split('/*/');return(inputs[root]??[]).map(id=>`${root}/#${id}/${suffix}`);}
function dependencies(f,p){const out=[];function walk(x){if(!x)return;if(x.op==='Dependency'){let d=x.path;if(p.includes('/#')&&d.includes('/*/'))d=d.replace('/*/','/'+p.split('/')[2]+'/');if(d.includes('/*/')){const [r,s]=d.split('/*/');out.push(r,...(inputs[r]??[]).map(id=>r+'/#'+id+'/'+s));}else out.push(engine.definitions.has(d)?d:d.endsWith('/year')?d.slice(0,-5):d);}for(const a of x.args??[])if(typeof a==='object')walk(a);}walk(f.formula);return [...new Set(out)];}
function read(p){return engine.result(graph,p);}
function money(v){if(v===null)return'Unknown';const [whole,decimal='00']=String(v).split('.');return '$'+whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+decimal.padEnd(2,'0');}
function display(p){const r=read(p),f=engine.definitions.get(canonical(p));if(!r.complete)return 'Unanswered';if(f?.type==='Dollar')return money(r.value);if(f?.type==='Boolean')return r.value==='true'?'Yes':'No';if(f?.type==='Collection')return `${inputs[p]?.length??0} records`;return r.value;}
function counts(index){const fs=catalogue.facts.filter(f=>groups[index][1].includes(f.module)&&!f.formula);const paths=fs.flatMap(concrete);return [paths.filter(p=>inputs[p]!==undefined).length,paths.length];}
function toast(text){$('#toast').textContent=text;setTimeout(()=>$('#toast').textContent='',3200);}
function update(){
 graph=engine.build(inputs);
 const constraints=engine.constraints(inputs),bad=Object.keys(errors).length;
 const notices=[...constraints,...(bad?[`${bad} field${bad===1?' has':'s have'} an invalid value. Correct the highlighted fields before exporting.`]:[])];
 $('#constraint-errors').innerHTML=notices.map(s=>`<div>${esc(s)}</div>`).join('');
 $('#provided').textContent=Object.keys(inputs).length;
 $('#fact-count').textContent=`${catalogue.facts.length} dictionary definitions`;
 const ready=read('/review/coreReady').value==='true'&&!notices.length&&inputs['/return/currency']==='CAD'&&inputs['/return/taxYear']!==undefined&&inputs['/return/ruleVersion']&&inputs['/return/sourceSnapshot'];
 const total=read('/taxableIncome/amount'),net=read('/income/netIncome');
 for(const [id,path] of [['federal-total','netFederalTax'],['total-payable','totalPayable'],['total-payments','totalCreditsAndPayments']]){const r=read('/federalTax/'+path);$('#'+id).textContent=ready&&r.complete?money(r.value):'Awaiting inputs / review';}
 const balance=read('/federalTax/netPayable');$('#balance-total').textContent=ready&&balance.complete?money(String(Math.abs(Number(balance.value)))):'Awaiting inputs / review';$('#balance-label').textContent=balance.complete&&ready?(Number(balance.value)<0?'Calculated refund':Number(balance.value)>0?'Balance owing':'Balanced return'):'Balance owing / refund';
 const provincial=read('/ns/taxPayable');
 $('#provincial').textContent=provincial.complete&&ready?money(provincial.value):'Awaiting inputs / review';
 $('#provincial-status').textContent=read('/ns/yearSupported').value==='false'?'Supported years: 2025 and 2026':inputs['/residence/provinceAtYearEnd']&&inputs['/residence/provinceAtYearEnd']!=='NS'?'Nova Scotia residents only':'NS income tax · excludes federal tax and payments';
 $('#net').textContent=!net.complete?'Awaiting inputs':ready?money(net.value):'Awaiting review';
 $('#taxable').textContent=!total.complete?'Awaiting inputs':ready?money(total.value):'Awaiting review';
 $('#review-status').textContent=ready?'Core income reviewed':'Review and return metadata required before use';
 $('#export').disabled=!!bad;$('#export-nodes').disabled=!!bad;
 $('#steps').innerHTML=groups.map((g,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}><span class="step-index">${i+1}</span><span>${esc(g[0])}</span></button>`).join('');
 const[a,b]=counts(step);$('#section-progress').textContent=`${a} / ${b} provided`;
 document.querySelectorAll('[data-result]').forEach(el=>el.textContent=display(el.dataset.result));
 if(view==='graph')renderGraph();
}
function refs(f){return (f.authorities??[]).map(a=>`<a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.label??'ITA')} ${esc(a.pinpoint)} ↗</a>`).join(' · ');}
function field(f,p){
 const linked=inputs['/schedules/useDonations']===true?{'/credits/donations':'/schedule9/federalCredit','/ns/eligibleDonations':'/schedule9/claimedGifts'}:{};
 if(inputs['/schedules/useRrsp']===true)Object.assign(linked,{'/registeredPlans/rrspDeduction':'/schedule7/deduction','/registeredPlans/hbpIncomeInclusion':'/schedule7/hbpShortfall','/registeredPlans/llpIncomeInclusion':'/schedule7/llpShortfall'});
 if(linked[p])return `<div class="derived-row"><div><button data-inspect="${linked[p]}">${esc(label(p))} ↗</button><p class="description">Linked from the enabled schedule. The saved manual value is ignored.</p></div><strong data-result="${linked[p]}">${esc(display(linked[p]))}</strong></div>`;
const id=fieldId(p),value=drafts[p]??inputs[p]??'',status=f.kind==='reviewed_input'?'Reviewed amount / decision':f.kind==='metadata'?'Record metadata':f.type==='Dollar'?'CAD':'',opts=f.type==='Boolean'?[['true','Yes'],['false','No']]:f.values?.map(v=>[v,label(v)]);let control;
 if(opts)control=`<select id="${id}" data-path="${esc(p)}" aria-describedby="${id}-help ${id}-error"><option value="">Unanswered</option>${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
 else control=`<input id="${id}" data-path="${esc(p)}" type="${f.type==='Day'?'date':'text'}" ${['Dollar','Int'].includes(f.type)?'inputmode="decimal"':''} value="${esc(value)}" placeholder="${f.type==='Dollar'?'0.00 — only if confirmed':'Unanswered'}" autocomplete="off" aria-invalid="${!!errors[p]}" aria-describedby="${id}-help ${id}-error">`;
 return `<div class="field"><div class="field-header"><label for="${id}">${esc(label(f.path))}</label><span class="kind">${status}</span></div><p class="description" id="${id}-help">${esc(f.definition)}</p>${control}<div class="error" id="${id}-error">${esc(errors[p]??'')}</div><div class="field-meta">${refs(f)}</div><details><summary>Fact path${f.nonnegative?' · minimum 0':''}</summary><code>${esc(p)}</code>${f.notes?`<p class="description">${esc(f.notes)}</p>`:''}</details></div>`;
}
function collection(f){const ids=inputs[f.path],children=catalogue.facts.filter(x=>x.path.startsWith(f.path+'/*/')&&!x.formula);return `<section class="collection"><div class="collection-head"><h3>${esc(label(f.path))}</h3><span class="badge">${ids===undefined?'Unanswered':ids.length+' records'}</span></div><p class="description">${esc(f.definition)}</p><div class="collection-controls"><button data-add="${f.path}">+ Add record</button>${ids?.length?'':`<button data-empty="${f.path}">Confirm none apply</button>`}${ids!==undefined?`<button data-unset="${f.path}">Clear response</button>`:''}</div>${ids===undefined?'<p class="collection-state">No response yet. Confirm none apply if this collection is empty.</p>':ids.length?'':'<p class="collection-state">Confirmed: no records.</p>'}${(ids??[]).map((id,i)=>`<div class="record"><div class="record-title"><h3>${esc(label(f.path))} · ${i+1}</h3><button data-remove="${f.path}/#${id}">Remove record</button></div>${children.map(c=>field(c,c.path.replace('*','#'+id))).join('')}</div>`).join('')}</section>`;}
function renderStep(){
 const [name,modules,intro]=groups[step];$('#section-title').textContent=name;$('#step-number').textContent=`SECTION ${String(step+1).padStart(2,'0')}`;$('#section-intro').textContent=intro;
 $('#fields').innerHTML=modules.map(mod=>{const fs=catalogue.facts.filter(f=>f.module===mod&&!f.path.includes('/*/')&&!f.ui?.hidden);if(!fs.length)return'';return `<h3 class="group-title">${esc(label(mod))}</h3>`+fs.map(f=>f.type==='Collection'?collection(f):f.formula?`<div class="derived-row"><div><button data-inspect="${f.path}">${esc(label(f.path))} ↗</button><p class="description">${esc(f.module==='nextYearRrsp'?f.definition:'Calculated fact')}</p></div><strong data-result="${f.path}">${esc(display(f.path))}</strong></div>`:field(f,f.path)).join('');}).join('');
 $('#previous').disabled=step===0;$('#next').textContent=step===groups.length-1?'Explore graph →':'Next section →';$('#step-position').textContent=`${step+1} of ${groups.length}`;update();
}
function chooseStep(i){step=i;setView('interview');renderStep();$('#main').scrollIntoView({behavior:'smooth',block:'start'});}
function setView(v){view=v;$('#interview').hidden=v!=='interview';$('#graph-view').hidden=v!=='graph';$('#interview-tab').setAttribute('aria-selected',v==='interview');$('#graph-tab').setAttribute('aria-selected',v==='graph');if(v==='graph')renderGraph();}
function node(p,focus=false){return `<button class="node ${read(p).complete?'complete':''} ${focus?'focus':''}" data-inspect="${esc(p)}">${esc(label(p))}<span>${esc(display(p))}</span></button>`;}
function renderGraph(){
 const paths=catalogue.facts.flatMap(concrete);if(!paths.includes(selected))selected='/taxableIncome/amount';const f=engine.definitions.get(canonical(selected));
 $('#fact-select').innerHTML=groups.map(g=>`<optgroup label="${esc(g[0])}">${paths.filter(p=>g[1].includes(engine.definitions.get(canonical(p)).module)).map(p=>`<option value="${esc(p)}" ${p===selected?'selected':''}>${esc(p)}</option>`).join('')}</optgroup>`).join('');
 const before=dependencies(f,selected),after=paths.filter(p=>dependencies(engine.definitions.get(canonical(p)),p).includes(selected));
 $('#graph-diagram').innerHTML=`<div class="graph-columns"><div class="graph-col"><small>Depends on · ${before.length}</small>${before.length?before.map(p=>node(p)).join(''):'<p class="graph-empty">Provided by you</p>'}</div><div class="graph-col"><small>Selected fact</small>${node(selected,true)}</div><div class="graph-col"><small>Used by · ${after.length}</small>${after.length?after.map(p=>node(p)).join(''):'<p class="graph-empty">No downstream expression</p>'}</div></div>`;
 $('#fact-detail').innerHTML=`<code>${esc(selected)}</code><p>${esc(f.definition)}</p><p>${f.formula?'Calculated by IRS Fact Graph. Arithmetic values shown here are for inspection; review gates still apply.':f.kind==='reviewed_input'?'This fact requires an external legal determination.':'This fact is supplied by the user.'}</p><p>${refs(f)}</p>${f.formula?`<details><summary>Calculation expression</summary><pre>${esc(JSON.stringify(f.formula,null,2))}</pre></details>`:`<button data-edit="${esc(selected)}">Edit this fact →</button>`}`;
}
function download(name,obj){const url=URL.createObjectURL(new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmation(title,body,fn){$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;$('#confirm-action').onclick=()=>{$('#confirm').close();fn();};$('#confirm').showModal();}
function clearCollection(p){delete inputs[p];for(const target of [inputs,drafts,errors])for(const k of Object.keys(target))if(k.startsWith(p+'/#'))delete target[k];}
function changeField(el){const p=el.dataset.path,f=engine.definitions.get(canonical(p)),raw=el.value,previousValue=inputs[p];delete errors[p];delete drafts[p];delete inputs[p];if(raw!==''){const v=f.type==='Boolean'?raw==='true':raw;try{engine.validate(p,v);inputs[p]=v;}catch(e){drafts[p]=raw;errors[p]=e.message;}}
 if(p==='/return/taxYear'&&String(previousValue??'')!==raw){delete inputs['/return/annualParametersReviewed'];delete inputs['/ns/creditsReviewed'];delete inputs['/federalTax/returnReviewed'];}
 if(p==='/federalTax/creditInputBasis'&&String(previousValue??'')!==raw)delete inputs['/federalTax/returnReviewed'];
 if(p==='/return/taxYear'){delete inputs['/schedule9/reviewed'];delete inputs['/schedule7/reviewed'];}
 if(p.startsWith('/schedules/')){delete inputs['/schedule9/reviewed'];delete inputs['/federalTax/returnReviewed'];delete inputs['/ns/creditsReviewed'];if(p==='/schedules/useRrsp'){delete inputs['/schedule7/reviewed'];delete inputs['/review/deductionEligibilityReviewed'];}}
 el.setAttribute('aria-invalid',!!errors[p]);document.getElementById(fieldId(p)+'-error').textContent=errors[p]??'';
 try{update();}catch(e){delete inputs[p];drafts[p]=raw;errors[p]=e.message;el.setAttribute('aria-invalid','true');document.getElementById(fieldId(p)+'-error').textContent=e.message;update();}
 if(p==='/return/taxYear'||p.startsWith('/schedules/'))renderStep();
}
async function start(){
 const loaded=await loadDictionaries(async path=>{const r=await fetch(path);if(!r.ok)throw Error('Dictionary unavailable: '+path);return r.text();});catalogue=loaded.catalogue;catalogue.facts.sort((a,b)=>(a.path==='/federalTax/creditInputBasis'?-1:0)-(b.path==='/federalTax/creditInputBasis'?-1:0));for(const f of catalogue.facts){if(f.path==='/credits/basicPersonal'){f.definition='Optional basic personal override: enter a claim base in Claim amounts mode or a final reduction in Credit dollars mode. Leave blank for automatic calculation.';}if(f.path.startsWith('/credits/')){const finalOnly=['donations','topUp','dividend','foreign','political'].includes(f.path.split('/').at(-1));f.notes=finalOnly?'Always enter final credit dollars. This field is not multiplied by the ordinary credit rate.':'Follow Credit input basis: claim amounts before the rate, or already-calculated credit dollars.';if(f.path!=='/credits/basicPersonal')f.definition=f.notes+' Review eligibility and limits before entry.';}if(f.path==='/specialTaxes/minimumTax')f.definition='Final line 41700 amount determined by T691. Used only when Use minimum tax schedule is Yes under Federal tax. This replaces regular tax; it is not an added amount.';}engine=makeEngine(catalogue,loaded.xml);graph=engine.build(inputs);$('#boot').hidden=true;$('#app').hidden=false;renderStep();
 $('#steps').addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(b)chooseStep(Number(b.dataset.step));});
 $('#fields').addEventListener('change',e=>{if(e.target.dataset.path)changeField(e.target);});
 $('#fields').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add){inputs[b.dataset.add]=[...(inputs[b.dataset.add]??[]),crypto.randomUUID()];update();renderStep();}if(b.dataset.empty){inputs[b.dataset.empty]=[];update();renderStep();}if(b.dataset.unset){const p=b.dataset.unset;const action=()=>{clearCollection(p);update();renderStep();};if(inputs[p]?.length)confirmation('Clear this collection?','Its records and entered values will be removed from this tab.',action);else action();}if(b.dataset.remove){const p=b.dataset.remove;confirmation('Remove this record?','All values for this record will be removed.',()=>{const [group,id]=p.split('/#');inputs[group]=inputs[group].filter(v=>v!==id);for(const target of [inputs,drafts,errors])for(const k of Object.keys(target))if(k.startsWith(p+'/'))delete target[k];update();renderStep();});}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(b){selected=b.dataset.inspect;setView('graph');}const edit=e.target.closest('[data-edit]');if(edit){const p=edit.dataset.edit;chooseStep(groups.findIndex(g=>g[1].includes(engine.definitions.get(canonical(p)).module)));document.getElementById(fieldId(p))?.focus();}});
 $('#previous').onclick=()=>chooseStep(Math.max(0,step-1));$('#next').onclick=()=>step===groups.length-1?setView('graph'):chooseStep(step+1);
 $('#interview-tab').onclick=()=>setView('interview');$('#graph-tab').onclick=()=>setView('graph');$('#fact-select').onchange=e=>{selected=e.target.value;renderGraph();};$('#cancel').onclick=()=>$('#confirm').close();
 $('#reset').onclick=()=>confirmation('Clear all answers?','Export your fact graph first if you want to keep it.',()=>{inputs={};drafts={};errors={};update();chooseStep(0);});
 $('#example').onclick=()=>confirmation('Load the worked example?','This replaces answers with fictional amounts: $60,000 remuneration, $1,200 benefits, a $1,000 employment deduction, $2,000 property income, a $5,000 business loss, and a $7,000 income deduction. All additional Nova Scotia claims and adjustments are set to zero for a fictional 2025 full-year NS resident born in 1990. Federal credits other than basic personal are zero; fictional tax withheld is $10,000. Review attestations remain unanswered.',()=>{const id=crypto.randomUUID();inputs={'/return/currency':'CAD','/employments':[id],[`/employments/#${id}/remuneration`]:'60000',[`/employments/#${id}/benefits`]:'1200',[`/employments/#${id}/optionBenefits`]:'0',[`/employments/#${id}/deductions`]:'1000','/businesses':[id],[`/businesses/#${id}/net`]:'-5000','/properties':[id],[`/properties/#${id}/net`]:'2000','/otherIncome':[],'/subdivisionEDeductions':[id],[`/subdivisionEDeductions/#${id}/amount`]:'7000','/divisionCDeductions':[],'/taxableIncome/divisionCAdditions':'0','/capital/taxableGainsExcludingLpp':'0','/capital/taxableNetLppGain':'0','/capital/allowableLossesExcludingLpp':'0','/capital/abil':'0'};for(const f of catalogue.facts.filter(f=>f.path.startsWith('/ns/')&&!f.formula&&f.module!=='nsSetup'))inputs[f.path]=f.type==='Boolean'?false:f.type==='Int'?'0':'0';Object.assign(inputs,{'/return/ruleVersion':'canada-federal-0.1.0+nova-scotia-0.2.0','/return/sourceSnapshot':'federal-2026-06-21+ns-release-80-2026-04-23','/return/taxYear':'2025','/residence/status':'residentFullYear','/residence/provinceAtYearEnd':'NS','/person/birthDate':'1990-01-01','/ns/ordinaryReturnConfirmed':true});for(const f of catalogue.facts.filter(f=>!f.formula&&(f.path.startsWith('/federalTax/')||f.module==='credits'||['/payments/taxWithheld','/payments/instalments','/specialTaxes/splitIncome','/specialTaxes/minimumTaxCarryover','/specialTaxes/oasRecovery'].includes(f.path)))){if(f.path==='/credits/basicPersonal'||f.path==='/federalTax/returnReviewed')continue;inputs[f.path]=f.type==='Boolean'?false:'0';}inputs['/federalTax/creditInputBasis']='claimAmounts';inputs['/federalTax/ordinaryReturnConfirmed']=true;inputs['/payments/taxWithheld']='10000';inputs['/return/ruleVersion']='canada-federal-0.1.0+ns-0.2.0+federal-tax-0.3.1';drafts={};errors={};update();chooseStep(2);toast('Example loaded: $50,200 taxable income; $4,593.37 NS tax before review gates.');});
 $('#import').onclick=()=>$('#import-file').click();
 $('#import-file').onchange=async event=>{
  const file=event.target.files?.[0];event.target.value='';if(!file)return;
  $('#import').disabled=true;$('#import-status').textContent='Reading JSON…';
  try{
   if(file.size>MAX_IMPORT_BYTES)throw Error('Choose a JSON file smaller than 10 MB.');
   const candidate=prepareImport(await file.text(),engine);
   $('#import-status').textContent='';
   confirmation('Import saved answers?',`${candidate.format}: ${candidate.count} answers, ${candidate.collections} collections. This replaces all current answers. Calculations will be recomputed using the current dictionaries. ${candidate.clearedReviews} saved review confirmations will be cleared for a fresh review.${candidate.warnings.length?' The imported answers also have '+candidate.warnings.length+' review notices, which will be shown in the form.':''}`,()=>{
    inputs=candidate.inputs;graph=candidate.graph;drafts={};errors={};selected='/taxableIncome/amount';chooseStep(0);
    $('#import-status').textContent=`Imported ${candidate.count} answers. Complete the review confirmations before using the tax results.`;
    toast('Saved answers imported.');
   });
  }catch(error){$('#import-status').textContent='Import failed. '+error.message+' Current answers were kept.';}
  finally{$('#import').disabled=false;}
 };
 $('#export').onclick=()=>{download('canadian-tax-fact-graph.json',graph.toJSON());toast('Exported in native IRS Fact Graph format.');};
 $('#export-nodes').onclick=()=>{const paths=catalogue.facts.flatMap(concrete);download('canadian-tax-graph-nodes.json',{format:'canadian-tax-graph',catalogueVersion:catalogue.version,dictionaryModules:catalogue.modules,exportedAt:new Date().toISOString(),coreReviewAttested:read('/review/coreReady').value==='true',constraints:engine.constraints(inputs),nodes:paths.map(p=>({path:p,type:engine.definitions.get(canonical(p)).type,...read(p)})),edges:paths.flatMap(p=>dependencies(engine.definitions.get(canonical(p)),p).map(d=>({from:d,to:p}))),inputs,nativeGraph:JSON.parse(graph.toJSON())});};
}
start().catch(e=>{$('#boot').textContent='The fact graph could not be loaded. '+e.message;console.error(e);});
